import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { useMutation, useQuery, useQueryClient } from 'react-query';
import { useNavigate, useParams } from 'react-router-dom';
import {
  createPrompt,
  updatePrompt,
  getPromptById,
} from '../api/prompts'; // Make sure these exist
import toast from 'react-hot-toast';

const CreatePrompt = ({ isEditMode = false }) => {
  const { id } = useParams();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const [tags, setTags] = useState([]);
  const [isPublic, setIsPublic] = useState(true);
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    reset,
    formState: { errors },
  } = useForm();

  // Get existing prompt data in edit mode
  const {
    data: existingPrompt,
    isLoading: isFetchingPrompt,
  } = useQuery(['prompt', id], () => getPromptById(id), {
    enabled: isEditMode,
  });

  // Pre-fill form when editing
  useEffect(() => {
    if (isEditMode && existingPrompt) {
      reset({
        title: existingPrompt.title,
        content: existingPrompt.content,
        description: existingPrompt.description,
        category: existingPrompt.category || 'other',
      });
      setTags(existingPrompt.tags || []);
      setIsPublic(existingPrompt.isPublic);
    }
  }, [isEditMode, existingPrompt, reset]);

  // Create mutation
  const createMutation = useMutation(createPrompt, {
    onSuccess: (data) => {
      toast.success('Prompt created!');
      queryClient.invalidateQueries(['prompts']);
      navigate(`/prompts/${data._id}`);
    },
    onError: (err) => {
      toast.error(err.response?.data?.message || 'Failed to create prompt');
    },
  });

  // Update mutation
  const updateMutation = useMutation(updatePrompt, {
    onSuccess: (data) => {
      toast.success('Prompt updated!');
      queryClient.invalidateQueries(['prompts']);
      navigate(`/prompts/${data._id}`);
    },
    onError: (err) => {
      toast.error(err.response?.data?.message || 'Failed to update prompt');
    },
  });

  const onSubmit = async (data) => {
    setIsLoading(true);
    try {
      if (isEditMode) {
        await updateMutation.mutateAsync({
          id,
          ...data,
          tags,
          isPublic,
        });
      } else {
        await createMutation.mutateAsync({
          ...data,
          tags,
          isPublic,
        });
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleTagChange = (e) => {
    const newTags = e.target.value.split(',').map((tag) => tag.trim());
    setTags(newTags);
  };

  return (
    <div className="prompt-form">
      <h2>{isEditMode ? 'Edit Prompt' : 'Create Prompt'}</h2>

      <form onSubmit={handleSubmit(onSubmit)}>
        <div>
          <label>Title</label>
          <input {...register('title', { required: true })} />
          {errors.title && <p>Title is required</p>}
        </div>

        <div>
          <label>Description</label>
          <textarea {...register('description')} />
        </div>

        <div>
          <label>Prompt Content</label>
          <textarea {...register('content', { required: true })} />
          {errors.content && <p>Content is required</p>}
        </div>

        <div>
          <label>Category</label>
          <select {...register('category')}>
            <option value="writing">Writing</option>
            <option value="coding">Coding</option>
            <option value="marketing">Marketing</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div>
          <label>Tags (comma separated)</label>
          <input
            value={tags.join(', ')}
            onChange={handleTagChange}
            placeholder="e.g. ai, code, writing"
          />
        </div>

        <div>
          <label>
            <input
              type="checkbox"
              checked={isPublic}
              onChange={(e) => setIsPublic(e.target.checked)}
            />
            Public Prompt
          </label>
        </div>

        <button type="submit" disabled={isLoading}>
          {isLoading
            ? isEditMode
              ? 'Updating...'
              : 'Creating...'
            : isEditMode
            ? 'Update Prompt'
            : 'Create Prompt'}
        </button>
      </form>
    </div>
  );
};

export default CreatePrompt;
